import React from 'react';
import {
  LineChart, Line, XAxis, YAxis, Tooltip, CartesianGrid, Legend, ResponsiveContainer
} from 'recharts';
import { useTranslation } from 'react-i18next';

export default function LineChartComponent({ data, provinces }) {
  const { t } = useTranslation();
  if (!data.length) return null;

  const dates = [...new Set(data.map(d => d.date))].sort();
  const chartData = dates.map(date => {
    const entry = { date };
    provinces.forEach(prov => {
      const pt = data.find(d => d.date === date && d.province === prov);
      entry[prov] = pt ? pt.value : null;
    });
    return entry;
  });

  // Define modern, accessible colors with good contrast
  const provinceColors = {
    'Ontario': '#3B82F6',      // Blue
    'Quebec': '#10B981',       // Green
    'British Columbia': '#F59E0B'  // Amber
  };

  // Custom tooltip for better context
  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
      return (
        <div style={{
          backgroundColor: 'rgba(255, 255, 255, 0.95)',
          border: '1px solid #e5e7eb',
          borderRadius: '8px',
          padding: '12px',
          boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
          fontSize: '14px'
        }}>
          <p style={{ 
            margin: '0 0 8px 0', 
            fontWeight: '600', 
            color: '#374151',
            borderBottom: '1px solid #e5e7eb',
            paddingBottom: '4px'
          }}>
            {label}
          </p>
          {payload.map((entry, index) => (
            <p key={index} style={{ 
              margin: '4px 0', 
              color: '#6B7280',
              display: 'flex',
              alignItems: 'center',
              gap: '8px'
            }}>
              <span style={{
                display: 'inline-block',
                width: '12px',
                height: '12px',
                backgroundColor: entry.color,
                borderRadius: '2px'
              }}></span>
              <span style={{ fontWeight: '500' }}>{entry.name}:</span>
              <span style={{ fontWeight: '600', color: '#111827' }}>
                ${entry.value?.toFixed(2)}
              </span>
            </p>
          ))}
        </div>
      );
    }
    return null;
  };

  return (
    <div style={{
      backgroundColor: 'white',
      borderRadius: '12px',
      padding: '24px',
      boxShadow: '0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06)',
      marginBottom: '24px'
    }}>
      <h2 style={{
        margin: '0 0 20px 0',
        fontSize: '20px',
        fontWeight: '600',
        color: '#111827',
        textAlign: 'center'
      }}>
        {t('line_chart_title', { type: data[0]?.type ? t(`food_types.${data[0].type}`) : '' })}
      </h2>

      <ResponsiveContainer width="100%" height={400}>
        <LineChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
          {/* Subtle grid for context without clutter */}
          <CartesianGrid 
            strokeDasharray="3 3" 
            stroke="#F3F4F6" 
            vertical={false}
          />

          <XAxis 
            dataKey="date" 
            stroke="#6B7280"
            fontSize={12}
            tickLine={false}
            axisLine={{ stroke: '#E5E7EB' }}
            tickFormatter={(value) => {
              const [year, month] = value.split('-');
              return `${month}/${year.slice(2)}`;
            }}
          />

          <YAxis 
            domain={['dataMin - 0.1', 'dataMax + 0.1']}
            tickFormatter={(value) => `$${value.toFixed(1)}`}
            stroke="#6B7280"
            fontSize={12}
            tickLine={false}
            axisLine={{ stroke: '#E5E7EB' }}
          />

          <Tooltip content={<CustomTooltip />} />

          <Legend 
            verticalAlign="top" 
            height={36}
            wrapperStyle={{
              paddingBottom: '16px'
            }}
          />

          {provinces.map(prov => (
            <Line 
              key={prov} 
              type="monotone" 
              dataKey={prov} 
              name={prov}
              stroke={provinceColors[prov]}
              strokeWidth={3}
              dot={{ 
                fill: provinceColors[prov], 
                strokeWidth: 2, 
                r: 4,
                stroke: 'white'
              }}
              activeDot={{ 
                r: 6, 
                strokeWidth: 2,
                stroke: 'white',
                fill: provinceColors[prov]
              }}
              connectNulls={false}
            />
          ))}
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}
